"""Generated bytes exercise acquisition safety, literal accounting and admission."""

import copy
import importlib.util
import io
import json
import zipfile
from pathlib import Path
from types import SimpleNamespace

import pytest

ROOT = Path(__file__).resolve().parents[1]
MODULE = importlib.util.spec_from_file_location(
    "upstream_revision", ROOT / "scripts/compare_upstream_shuttle_revision.py"
)
revision = importlib.util.module_from_spec(MODULE)
MODULE.loader.exec_module(revision)
CSV = b"Frame,Visibility,X,Y\n0,1,3,4\n1,2,0,0\n"


class Response(io.BytesIO):
    status = 200

    def __init__(self, raw, url):
        super().__init__(raw)
        self.url = url

    def geturl(self):
        return self.url


class Opener:
    def __init__(self, raw=CSV, url="https://example.invalid/pinned"):
        self.raw, self.url, self.calls = raw, url, 0

    def open(self, request, timeout):
        assert request.get_header("Authorization") is None
        assert request.get_header("Cookie") is None
        assert timeout == 45
        self.calls += 1
        return Response(self.raw, self.url)


def test_manifest_and_policy_are_pinned():
    spec = json.loads(revision.MANIFEST.read_bytes())
    revision.validate_manifest(spec)
    for name, value in (("original_basis", {}), ("alias_mapping", True)):
        changed = copy.deepcopy(spec)
        changed[name] = value
        with pytest.raises(ValueError):
            revision.validate_manifest(changed)
    changed = copy.deepcopy(spec)
    changed["corrected_objects"][0]["bytes"] += 1
    with pytest.raises(ValueError, match="inventory"):
        revision.validate_manifest(changed)


def test_network_no_retry_auth_redirect_or_unlisted_destination(tmp_path):
    url = "https://example.invalid/pinned"
    opener = Opener()
    network = revision.Network(tmp_path, [url], opener)
    with pytest.raises(ValueError, match="allowlist"):
        network.fetch("https://example.invalid/other")
    assert opener.calls == 0
    assert network.fetch(url) == CSV
    assert (network.requests, network.bytes) == (1, len(CSV))
    with pytest.raises(ValueError, match="replay"):
        network.fetch(url)
    assert opener.calls == 1
    reloaded = revision.Network(tmp_path, [url], opener)
    assert (reloaded.requests, reloaded.bytes) == (1, len(CSV))


@pytest.mark.parametrize("mode", ["oversize", "redirect", "interrupted"])
def test_failed_acquisition_is_preserved_and_never_retried(tmp_path, monkeypatch, mode):
    url = "https://example.invalid/pinned"
    monkeypatch.setattr(revision, "MAX_RESPONSE", 20)
    opener = Opener(b"x" * 21 if mode == "oversize" else b"ok", url)
    if mode == "redirect":
        opener.url = "https://example.invalid/redirected"
    if mode == "interrupted":

        def fail(*args, **kwargs):
            raise TimeoutError("Generated interruption")

        opener.open = fail
    network = revision.Network(tmp_path, [url], opener)
    with pytest.raises((ValueError, TimeoutError)):
        network.fetch(url)
    assert len(list(tmp_path.glob("request-*.json"))) == 1
    with pytest.raises(ValueError):
        network.fetch(url)
    if mode == "oversize":
        assert next(tmp_path.glob("response-*.bin")).read_bytes() == b"x" * 20
    else:
        with pytest.raises(ValueError, match="incomplete"):
            revision.Network(tmp_path, [url], opener)


def test_network_fixed_request_and_total_bounds(tmp_path, monkeypatch):
    url = "https://example.invalid/pinned"
    network = revision.Network(tmp_path, [url], Opener(b"abc"))
    network.requests = revision.MAX_REQUESTS
    with pytest.raises(ValueError, match="budget"):
        network.fetch(url)
    network.requests = 0
    monkeypatch.setattr(revision, "MAX_NETWORK", 3)
    with pytest.raises(ValueError, match="bound"):
        network.fetch(url)
    assert network.bytes == 3


def test_explicit_cache_reuse_does_not_repeat_successful_request(tmp_path):
    url = "https://example.invalid/pinned"
    opener = Opener()
    first = revision.Network(tmp_path, [url], opener)
    first.fetch(url)
    resumed = revision.Network(tmp_path, [url], opener, reuse_cached=True)
    assert resumed.fetch(url) == CSV
    assert opener.calls == resumed.requests == 1


def test_metadata_inventory_excludes_pinned_drop_document(tmp_path, monkeypatch):
    spec = json.loads(revision.MANIFEST.read_bytes())
    tree = {
        spec["upstream"]["prefix"] + o["path"]: {
            "sha": o["git_blob_sha"],
            "size": o["bytes"],
            "type": "blob",
        }
        for o in spec["corrected_objects"]
    }
    for path in ("correct_label.py", "corrected_test_label/drop_frame.json"):
        tree[path] = {
            "type": "blob",
            "sha": revision.git_object(b"generated metadata"),
            "size": 18,
        }
    monkeypatch.setattr(revision, "verify_tree", lambda *args: tree)
    source_manifest = json.loads(
        (ROOT / "data/manifests/shuttle_supervision_sources_v1.json").read_bytes()
    )
    archive = tmp_path / "empty.zip"
    with zipfile.ZipFile(archive, "w"):
        pass
    monkeypatch.setattr(revision, "census_archive", lambda *args: [])
    monkeypatch.setattr(
        revision,
        "literal_inventory",
        lambda *args: [{"original_member": {}} for _ in range(29)],
    )

    class GeneratedNetwork:
        requests = 10
        bytes = 123

        def fetch(self, url):
            if "/git/commits/" in url:
                return json.dumps(
                    {
                        "sha": spec["upstream"]["commit"],
                        "tree": {"sha": spec["upstream"]["tree"]},
                    }
                ).encode()
            if "/git/trees/" in url:
                return b"{}"
            return b"generated metadata"

    for item in spec["documentation"].values():
        item["sha256"] = revision.digest(b"generated metadata")
    receipt = revision.metadata(
        tmp_path, spec, archive, source_manifest, GeneratedNetwork()
    )
    assert (tmp_path / "drop_frame.json").is_file()
    assert receipt["label_contents_opened"] is False


def test_git_tree_reconstructed_including_nested_identity():
    blob = revision.git_object(b"generated")
    subtree = revision.git_object(b"100644 a.csv\0" + bytes.fromhex(blob), "tree")
    root = revision.git_object(b"40000 nested\0" + bytes.fromhex(subtree), "tree")
    response = {
        "sha": root,
        "truncated": False,
        "tree": [
            {"path": "nested", "mode": "040000", "type": "tree", "sha": subtree},
            {
                "path": "nested/a.csv",
                "mode": "100644",
                "type": "blob",
                "sha": blob,
                "size": 9,
            },
        ],
    }
    assert "nested/a.csv" in revision.verify_tree(response, root)
    corrupt = copy.deepcopy(response)
    corrupt["tree"][1]["sha"] = "0" * 40
    with pytest.raises(ValueError, match="content"):
        revision.verify_tree(corrupt, root)
    corrupt = copy.deepcopy(response)
    corrupt["tree"][1]["path"] = "orphan/a.csv"
    with pytest.raises(ValueError, match="Unbound"):
        revision.verify_tree(corrupt, root)
    response["truncated"] = True
    with pytest.raises(ValueError, match="Truncated"):
        revision.verify_tree(response, root)


def test_literal_union_never_guesses_filename_alias():
    member = {
        "kind": "labels",
        "namespace": "test",
        "match": "match1",
        "rally": "1_01_01",
    }
    revised = {
        "path": "match1/corrected_csv/2_01_01_ball.csv",
        "bytes": len(CSV),
        "git_blob_sha": revision.git_object(CSV),
    }
    cases = revision.literal_inventory([member], [revised])
    assert [c["case_id"] for c in cases] == ["match1.1_01_01", "match1.2_01_01"]
    assert cases[0]["revised_object"] is None
    assert cases[1]["original_member"] is None
    with pytest.raises(ValueError, match="Duplicate"):
        revision.literal_inventory([member, member], [revised])


def test_only_test_csv_opened_null_bases_and_all_unmatched_retained(
    tmp_path, monkeypatch
):
    archive = tmp_path / "generated.zip"
    path = "root/test/match1/ball_trajectory/1_01_01_ball.csv"
    member = {"path": path, "bytes": len(CSV)}
    correction = {
        "path": "match1/corrected_csv/2_01_01_ball.csv",
        "bytes": len(CSV),
        "git_blob_sha": revision.git_object(CSV),
    }
    with zipfile.ZipFile(archive, "w") as bundle:
        bundle.writestr(path, CSV)
        bundle.writestr("root/test/match1/video/1_01_01.mp4", b"Never open media")
        bundle.writestr(
            "root/professional/match1/ball_trajectory/1_01_01_ball.csv",
            b"Never open non-Test labels",
        )
    frozen = [
        {"case_id": "original", "original_member": member, "revised_object": None},
        {"case_id": "revised", "original_member": None, "revised_object": correction},
    ]
    revision.save(tmp_path / "literal-inventory.json", frozen)
    revision.save(tmp_path / "metadata.json", {"generated": True})
    opened = []
    original_open = zipfile.ZipFile.open

    def tracked(self, name, *args, **kwargs):
        opened.append(name)
        return original_open(self, name, *args, **kwargs)

    monkeypatch.setattr(zipfile.ZipFile, "open", tracked)
    spec = {"upstream": {"commit": "a" * 40, "prefix": "corrected_test_label/"}}

    class GeneratedNetwork:
        requests = 1
        bytes = len(CSV)

        def fetch(self, url):
            return CSV

    summary = revision.compare(tmp_path, spec, archive, GeneratedNetwork())
    assert opened == [path]
    assert summary["cases"] == summary["unscored_cases"] == 2
    assert (
        summary["original"]["known_records"] == summary["revised"]["known_records"] == 2
    )
    assert summary["original"]["unknown_record_count_cases"] == 1
    result = json.loads((tmp_path / "comparison.json").read_bytes())
    assert not any(result["eligibility"].values())
    assert all(case["comparison"] is None for case in result["cases"])
    inventory = json.loads((tmp_path / "comparison-inventory.json").read_bytes())
    assert all(case["quarantine_reasons"] for case in inventory["cases"])
    assert all(
        side["basis"] is None
        for c in inventory["cases"]
        for side in (c["original"], c["revised"])
        if side
    )
    with pytest.raises(FileExistsError):
        revision.compare(tmp_path, spec, archive, GeneratedNetwork())


@pytest.mark.parametrize("mutation", ["wrong_hash", "wrong_length", "copy_bound"])
def test_object_mismatch_stops_before_parsing(tmp_path, monkeypatch, mutation):
    original = ROOT / "data/manifests/shuttle_label_revision_sources_v1.json"
    obj = {
        "path": "match1/corrected_csv/1_01_01_ball.csv",
        "bytes": len(CSV),
        "git_blob_sha": revision.git_object(CSV),
    }
    if mutation == "wrong_hash":
        obj["git_blob_sha"] = "0" * 40
    elif mutation == "wrong_length":
        obj["bytes"] += 1
    else:
        monkeypatch.setattr(revision, "MAX_COPIES", 1)
    revision.save(
        tmp_path / "literal-inventory.json",
        [{"case_id": "changed", "original_member": None, "revised_object": obj}],
    )
    archive = tmp_path / "generated.zip"
    with zipfile.ZipFile(archive, "w"):
        pass

    class GeneratedNetwork:
        def fetch(self, url):
            return CSV

    with pytest.raises(ValueError):
        revision.compare(
            tmp_path, json.loads(original.read_bytes()), archive, GeneratedNetwork()
        )
    assert not (tmp_path / "comparison-inventory.json").exists()


def test_no_overwrite_input_pins_and_escape_rejection(tmp_path, monkeypatch):
    path = tmp_path / "original.csv"
    path.write_bytes(CSV)
    with pytest.raises(FileExistsError):
        revision.save_bytes(path, b"replacement")
    assert path.read_bytes() == CSV
    with pytest.raises(ValueError, match="hash"):
        revision.pinned(path, "0" * 64)
    with pytest.raises(ValueError, match="size"):
        revision.pinned(path, revision.digest(CSV), 1)
    with pytest.raises(ValueError, match="original root"):
        revision.local_path(tmp_path, path)

    def interrupted(*args):
        raise OSError("Generated publication interruption")

    monkeypatch.setattr(revision.os, "link", interrupted)
    with pytest.raises(OSError):
        revision.save_bytes(tmp_path / "new.csv", CSV)
    assert not (tmp_path / "new.csv").exists()


@pytest.mark.parametrize(
    "unsafe", ["../escape.csv", "root/test/../escape.csv", "NUL.csv"]
)
def test_reuses_safe_archive_census_before_any_member_open(tmp_path, unsafe):
    path = tmp_path / "unsafe.zip"
